export default function install(app){const style=document.createElement('style');style.id='prowise-footer-center-icon-box';style.textContent='#prowise-tools-center{top:2px;background:#dde3e8;padding:6px;border-radius:16px;gap:8px;box-sizing:border-box}';document.head.append(style);app.onCleanup(()=>style.remove());const group=document.getElementById('prowise-tools-center');return {groupPresent:!!group,icons:group?.querySelectorAll('button').length||0,color:group?getComputedStyle(group).backgroundColor:null}}